apps['image-compress']=page("Image Compressor & Resizer","Shrink JPG, PNG and WEBP images and resize them for websites, email and social media, without uploading them anywhere.",
"Choose an image, set a maximum width and quality, and download the smaller version. A live size comparison shows how much you saved.",
r"""<h2>Compress an image</h2><label for="f">Image file (JPG, PNG, WEBP)</label><input id="f" type="file" accept="image/*">
<div class="grid"><div><label for="w">Maximum width (pixels)</label><input id="w" type="number" min="16" max="16000" step="1" value="1600"></div><div><label for="q">Quality: <span id="qv">75%</span></label><input id="q" type="range" min="0.1" max="1" step="0.05" value="0.75"></div>
<div><label for="o">Output format</label><select id="o"><option value="image/jpeg">JPG (smallest for photos)</option><option value="image/webp">WEBP (modern, small)</option><option value="image/png">PNG (lossless)</option></select></div></div>
<button type="button" id="go" disabled>Compress image</button><p id="st" aria-live="polite">No image loaded yet.</p><img id="pv" alt="Preview of the compressed image" style="max-width:100%;display:none;border-radius:12px"><p><a id="dl" class="btn" hidden download>Download compressed image</a></p>""",
r"""let img=null,name='image',orig=0,lastUrl=null,tok=0;const $=id=>document.getElementById(id);
const IMG={kind:'image',types:/^image\//,ext:/\.(jpe?g|png|webp|gif|bmp|avif)$/i,maxMB:50,hint:'Choose a JPG, PNG or WEBP image.'};
const off=()=>{img=null;$('go').disabled=true;$('dl').hidden=true;$('pv').style.display='none'};
$('f').onchange=e=>{const file=e.target.files[0];if(!file)return;const my=++tok;off();const bad=GWB.checkFile(file,IMG);if(bad)return GWB.status('st',bad,'error');GWB.status('st','Loading image…');
const i=new Image();i.onload=()=>{if(my!==tok)return;if(i.naturalWidth*i.naturalHeight>120e6)return GWB.status('st',`This image is ${i.naturalWidth}×${i.naturalHeight} pixels, too large to process safely in a browser. Try a smaller image.`,'error');img=i;name=file.name.replace(/\.[^.]+$/,'')||'image';orig=file.size;$('go').disabled=false;run()};
i.onerror=()=>{if(my===tok)GWB.status('st',"We couldn't read this image. It may be damaged or in a format your browser doesn't support. Try a JPG, PNG or WEBP.",'error')};i.src=URL.createObjectURL(file)};
function run(){if(!img)return;const mw=GWB.num('w',{label:'Maximum width',int:true,min:16,max:16000});if(mw===null)return GWB.status('st','Please fix the maximum width. Your image is still loaded.','error');
return GWB.busy('go',async()=>{const s=Math.min(1,mw/img.naturalWidth),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*s));c.height=Math.max(1,Math.round(img.naturalHeight*s));const g=c.getContext('2d'),t=$('o').value;if(!g)throw new Error('no ctx');if(t==='image/jpeg'){g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height)}g.drawImage(img,0,0,c.width,c.height);
const b=await new Promise(r=>c.toBlob(r,t,+$('q').value));if(!b)throw new Error('toBlob failed');window.lastOut=b;const ext=t.split('/')[1].replace('jpeg','jpg');if(lastUrl)URL.revokeObjectURL(lastUrl);const u=lastUrl=URL.createObjectURL(b);$('pv').src=u;$('pv').style.display='block';$('dl').href=u;$('dl').download=name+'-compressed.'+ext;$('dl').hidden=false;const pct=Math.round((1-b.size/orig)*100);
GWB.status('st',`Original ${(orig/1024).toFixed(0)} KB (${img.naturalWidth}×${img.naturalHeight}) → ${(b.size/1024).toFixed(0)} KB (${c.width}×${c.height}). ${pct>=0?pct+'% smaller.':'Larger than the original; try JPG/WEBP or a lower quality.'}`)},{status:'st',busyText:'Compressing…',keepDisabled:()=>!img,message:()=>"We couldn't compress this image, possibly because it's too large for your device's memory. Try a smaller maximum width."})}
$('go').onclick=run;['w','q','o'].forEach(i=>$(i).addEventListener('change',()=>img&&run()));$('q').addEventListener('input',()=>$('qv').textContent=Math.round($('q').value*100)+'%');""")
apps['image-convert']=page("Image Converter: PNG, JPG & WEBP","Convert images between PNG, JPG and WEBP in bulk, right in your browser. No uploads, no limits, no watermarks.",
"Select one or more images, pick the target format, and download each converted file. Transparent areas get your chosen background color when converting to JPG.",
r"""<h2>Convert images</h2><label for="f">Images (select one or more)</label><input id="f" type="file" accept="image/*" multiple>
<div class="grid"><div><label for="to">Convert to</label><select id="to"><option value="image/png">PNG</option><option value="image/jpeg" selected>JPG</option><option value="image/webp">WEBP</option></select></div><div><label for="bg">Background for JPG (replaces transparency)</label><input id="bg" type="color" value="#ffffff"></div><div><label for="q">JPG/WEBP quality (0.1 to 1)</label><input id="q" type="number" min="0.1" max="1" step="0.05" value="0.9"></div></div>
<button type="button" id="go">Convert</button><p id="st" aria-live="polite"></p><ul id="list"></ul>""",
r"""const $=id=>document.getElementById(id);let urls=[];
const IMG={kind:'image',types:/^image\//,ext:/\.(jpe?g|png|webp|gif|bmp|avif)$/i,maxMB:50,hint:'Only images (JPG, PNG, WEBP) can be converted.'};
const load=f=>new Promise((res,rej)=>{const i=new Image(),u=URL.createObjectURL(f);i.onload=()=>{URL.revokeObjectURL(u);res(i)};i.onerror=()=>{URL.revokeObjectURL(u);rej(new Error('decode'))};i.src=u});
$('f').addEventListener('change',()=>GWB.clearError('f'));
$('go').onclick=()=>{const files=[...$('f').files];if(!files.length)return GWB.fieldError('f','Choose at least one image first.');const q=GWB.num('q',{label:'Quality',min:0.1,max:1,eg:'0.9'});if(q===null)return;
return GWB.busy('go',async()=>{const t=$('to').value,ext=t.split('/')[1].replace('jpeg','jpg');urls.forEach(u=>URL.revokeObjectURL(u));urls=[];$('list').innerHTML='';let ok=0;GWB.status('st','Converting…');
for(const f of files){const li=document.createElement('li');const bad=GWB.checkFile(f,IMG);if(bad){li.textContent=bad;$('list').append(li);continue}
try{const i=await load(f);if(i.naturalWidth*i.naturalHeight>120e6)throw new Error('too big');const c=document.createElement('canvas');c.width=i.naturalWidth;c.height=i.naturalHeight;const g=c.getContext('2d');if(t==='image/jpeg'){g.fillStyle=$('bg').value;g.fillRect(0,0,c.width,c.height)}g.drawImage(i,0,0);
const b=await new Promise(r=>c.toBlob(r,t,q));if(!b)throw new Error('encode');const a=document.createElement('a'),n=f.name.replace(/\.[^.]+$/,'')+'.'+ext;a.href=URL.createObjectURL(b);urls.push(a.href);a.download=n;a.textContent=`Download ${n} (${(b.size/1024).toFixed(0)} KB)`;li.append(a);ok++}
catch(e){li.textContent=`${f.name}: couldn't be read. It may be damaged, too large, or in an unsupported format.`}$('list').append(li)}
window.convCount=ok;GWB.status('st',`Converted ${ok} of ${files.length} image(s).`,ok<files.length?'error':'')},{status:'st',busyText:'Converting…'})};""")
apps['pdf-tools']=page("PDF Merge, Split & JPG to PDF","Merge PDFs, extract or split pages, and turn JPG or PNG images into a PDF, all inside your browser, with no uploads.",
"Pick a task, choose your files, and download the result. Files are processed on your device with the open-source pdf-lib library. Password-protected PDFs may not work.",
r"""<h2>PDF tools</h2><label for="mode">What do you want to do?</label><select id="mode"><option value="merge">Merge several PDFs into one</option><option value="split">Extract or split pages</option><option value="img">Convert images (JPG/PNG) to PDF</option></select>
<div id="p-merge"><label for="mf">PDF files (merged in the order selected)</label><input id="mf" type="file" accept="application/pdf,.pdf" multiple><button type="button" id="bm">Merge PDFs</button></div>
<div id="p-split" hidden><label for="sf">PDF file</label><input id="sf" type="file" accept="application/pdf,.pdf"><label for="rng">Pages to keep (e.g. 1-3, 5). Leave empty for all pages</label><input id="rng" placeholder="1-3, 5"><label class="check"><input type="checkbox" id="each"> Save each page as a separate PDF</label><button type="button" id="bs">Extract pages</button></div>
<div id="p-img" hidden><label for="if">Images (JPG, PNG, WEBP)</label><input id="if" type="file" accept="image/*" multiple><label for="ps">Page size</label><select id="ps"><option value="fit">Match each image</option><option value="a4">A4 with margins</option></select><button type="button" id="bi">Create PDF</button></div>
<div id="res" class="out" aria-live="polite" style="white-space:normal">Results will appear here.</div>""",
r"""const $=id=>document.getElementById(id),msg=(t,k)=>GWB.status('res',t,k),fr=m=>Object.assign(new Error(m),{friendly:m});let urls=[];
$('mode').onchange=()=>['merge','split','img'].forEach(m=>$('p-'+m).hidden=$('mode').value!==m);
['mf','sf','if','rng'].forEach(i=>$(i).addEventListener(i==='rng'?'input':'change',()=>GWB.clearError(i)));
const PDFT={kind:'PDF',types:/^application\/(x-)?pdf$/,ext:/\.pdf$/i,maxMB:150,hint:'Choose a .pdf file.'},IMGT={kind:'image',types:/^image\/(jpeg|png|webp|gif|bmp)$/,ext:/\.(jpe?g|png|webp|gif|bmp)$/i,maxMB:50,hint:'Choose JPG, PNG or WEBP images.'};
const pre=(fs,t)=>{for(const f of fs){const b=GWB.checkFile(f,t);if(b)throw fr(b)}};
function save(bytes,name,pages,append){const b=new Blob([bytes],{type:'application/pdf'});window.lastPdf=b;if(!append){$('res').innerHTML='';$('res').classList.remove('gwb-bad');urls.forEach(u=>URL.revokeObjectURL(u));urls=[]}const a=document.createElement('a');a.className='btn';a.href=URL.createObjectURL(b);urls.push(a.href);a.download=name;a.textContent=`Download ${name} (${pages} page${pages>1?'s':''}, ${(b.size/1024).toFixed(0)} KB)`;$('res').append(a)}
async function load(f){let d;try{d=await PDFLib.PDFDocument.load(await f.arrayBuffer(),{updateMetadata:false})}catch(e){if(/encrypt/i.test(e.message))throw fr(`"${f.name}" is password-protected. Open it, save a copy without the password, then try again.`);throw fr(`We couldn't read "${f.name}". It may be damaged or not a real PDF.`)}
if(d.isEncrypted)throw fr(`"${f.name}" is password-protected. Open it, save a copy without the password, then try again.`);if(!d.getPageCount())throw fr(`We couldn't find any pages in "${f.name}". It may be damaged.`);return d}
function parse(s,n){const r=[],bad=[],out=[];s.split(',').forEach(p=>{p=p.trim();if(!p)return;const m=p.match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m){bad.push(p);return}const a=+m[1],b=+(m[2]||m[1]);if(Math.max(a,b)>n||Math.min(a,b)<1)out.push(p);for(let i=Math.min(a,b);i<=Math.max(a,b)&&i<=n;i++)if(i>=1&&!r.includes(i-1))r.push(i-1)});return{r,bad,out}}
async function merge(){const fs=[...$('mf').files];if(fs.length<2)return GWB.fieldError('mf','Choose at least two PDF files to merge (hold Ctrl or Cmd to pick several).');GWB.need('PDFLib','PDF engine');pre(fs,PDFT);msg('Working…');const o=await PDFLib.PDFDocument.create();for(const f of fs){const d=await load(f);(await o.copyPages(d,d.getPageIndices())).forEach(p=>o.addPage(p))}save(await o.save(),'merged.pdf',o.getPageCount())}
async function split(){const f=$('sf').files[0];if(!f)return GWB.fieldError('sf','Choose a PDF file first.');GWB.need('PDFLib','PDF engine');pre([f],PDFT);msg('Working…');const d=await load(f),n=d.getPageCount();let idx=d.getPageIndices();
if($('rng').value.trim()){const p=parse($('rng').value,n);if(p.bad.length){msg('');return GWB.fieldError('rng',`"${p.bad[0]}" isn't a page number or range. Use numbers like 1-3, 5.`)}if(p.out.length){msg('');return GWB.fieldError('rng',`This PDF has ${n} pages, so "${p.out[0]}" is out of range. Pick pages between 1 and ${n}.`)}idx=p.r}
if(!idx.length){msg('');return GWB.fieldError('rng',`No valid pages in that range. This PDF has ${n} pages.`)}
if($('each').checked){$('res').innerHTML='';for(const i of idx){const o=await PDFLib.PDFDocument.create();o.addPage((await o.copyPages(d,[i]))[0]);save(await o.save(),`page-${i+1}.pdf`,1,true)}}else{const o=await PDFLib.PDFDocument.create();(await o.copyPages(d,idx)).forEach(p=>o.addPage(p));save(await o.save(),'extracted.pdf',idx.length)}}
async function toJpg(f){const bm=await createImageBitmap(f),c=document.createElement('canvas');c.width=bm.width;c.height=bm.height;const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);g.drawImage(bm,0,0);return new Promise((r,j)=>c.toBlob(b=>b?r(b):j(new Error('encode')),'image/jpeg',.92))}
async function imgs(){const fs=[...$('if').files];if(!fs.length)return GWB.fieldError('if','Choose at least one image first.');GWB.need('PDFLib','PDF engine');pre(fs,IMGT);msg('Working…');const o=await PDFLib.PDFDocument.create(),a4=$('ps').value==='a4';for(const f of fs){let im;try{if(f.type==='image/png')im=await o.embedPng(await f.arrayBuffer());else if(f.type==='image/jpeg')im=await o.embedJpg(await f.arrayBuffer());else im=await o.embedJpg(await (await toJpg(f)).arrayBuffer())}catch(e){throw fr(`We couldn't read the image "${f.name}". It may be damaged. Try re-saving it as JPG or PNG.`)}
const W=a4?595.28:im.width,H=a4?841.89:im.height,s=a4?Math.min((W-72)/im.width,(H-72)/im.height,1):1,p=o.addPage([W,H]);p.drawImage(im,{x:(W-im.width*s)/2,y:(H-im.height*s)/2,width:im.width*s,height:im.height*s})}save(await o.save(),'images.pdf',o.getPageCount())}
const wrap=(id,fn)=>()=>GWB.busy(id,fn,{status:'res',busyText:'Working…',message:e=>e&&e.friendly?e.friendly:(e instanceof RangeError?"Your browser ran out of memory. Try fewer or smaller files.":"Sorry, that file could not be processed. Encrypted or damaged PDFs may not work. Your selection is kept.")});
$('bm').onclick=wrap('bm',merge);$('bs').onclick=wrap('bs',split);$('bi').onclick=wrap('bi',imgs);""",head='<script src="../vendor/pdf-lib.min.js" defer data-gwb-lib="PDFLib" data-gwb-name="PDF engine"></script>')
apps['word-counter']=page("Word & Character Counter","Count words, characters, sentences and paragraphs as you type, with reading time, speaking time and top keywords.",
"Paste or type your text. Every number updates instantly, which is handy for essays, social posts, SEO meta descriptions and ad copy limits.",
r"""<h2>Count your text</h2><label for="t">Your text</label><textarea id="t" style="min-height:220px">Paste or type your text here. GWB counts words, characters and sentences instantly, right in your browser.</textarea>
<div class="grid" style="margin-top:18px" aria-live="polite"><div class="stat"><b id="w">0</b>Words</div><div class="stat"><b id="c">0</b>Characters</div><div class="stat"><b id="cn">0</b>Characters (no spaces)</div><div class="stat"><b id="s">0</b>Sentences</div><div class="stat"><b id="p">0</b>Paragraphs</div><div class="stat"><b id="rt">0 min</b>Reading time</div><div class="stat"><b id="sp">0 min</b>Speaking time</div></div>
<h3 style="margin-top:22px">Top keywords</h3><p id="kw" class="lead">None yet.</p><button type="button" class="alt" id="clr">Clear text</button>""",
r"""const $=id=>document.getElementById(id),STOP=new Set('the a an and or but of to in on for with at by from is are was were be been it this that as your you we our i they he she not can will just so if than then into about'.split(' '));
const L=n=>n.toLocaleString();
function up(){const t=$('t').value,w=t.match(/[\p{L}\p{N}'’-]+/gu)||[];let chars=0,nos=0;for(const ch of t){chars++;if(!/\s/.test(ch))nos++}$('w').textContent=L(w.length);$('c').textContent=L(chars);$('cn').textContent=L(nos);$('s').textContent=L(t.split(/[.!?…]+/).filter(x=>/[\p{L}\p{N}]/u.test(x)).length);$('p').textContent=L(t.split(/\n\s*\n/).filter(x=>x.trim()).length);
const m=x=>x<1&&x>0?'< 1 min':Math.ceil(x).toLocaleString()+' min';$('rt').textContent=m(w.length/238);$('sp').textContent=m(w.length/150);const f=new Map();for(let x of w){x=x.toLowerCase();if(x.length>2&&!STOP.has(x))f.set(x,(f.get(x)||0)+1)}const top=[...f].sort((a,b)=>b[1]-a[1]).slice(0,8);$('kw').textContent=top.length?top.map(([k,v])=>`${k} (${v})`).join(', '):'None yet.'}
let deb=null;const sched=()=>{clearTimeout(deb);$('t').value.length>100000?deb=setTimeout(up,200):up()};
$('t').addEventListener('input',sched);$('clr').onclick=()=>{$('t').value='';up();$('t').focus()};up();""")
apps['password']=page("Password Generator","Generate strong, random passwords instantly using your browser's secure random number generator. Nothing is sent or stored.",
"Choose a length and character types, then copy one of the generated passwords. We show an estimate of each password's strength in bits of entropy.",
r"""<h2>Generate passwords</h2><div class="grid"><div><label for="len">Length: <span id="lv">16</span></label><input id="len" type="range" min="8" max="64" value="16"></div>
<fieldset><legend>Include</legend><label class="check"><input type="checkbox" id="up" checked> Uppercase (A-Z)</label><label class="check"><input type="checkbox" id="lo" checked> Lowercase (a-z)</label><label class="check"><input type="checkbox" id="di" checked> Numbers (0-9)</label><label class="check"><input type="checkbox" id="sy" checked> Symbols (!@#…)</label><label class="check"><input type="checkbox" id="am"> Avoid look-alikes (O/0, l/1)</label></fieldset></div>
<button type="button" id="gen">Generate new passwords</button><p id="str" aria-live="polite"></p><ol id="list" style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:1.05rem"></ol>""",
r"""const $=id=>document.getElementById(id);
function pick(n){const a=new Uint32Array(1),lim=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a)}while(a[0]>=lim);return a[0]%n}
function gen(){let sets=[];if($('up').checked)sets.push('ABCDEFGHIJKLMNOPQRSTUVWXYZ');if($('lo').checked)sets.push('abcdefghijklmnopqrstuvwxyz');if($('di').checked)sets.push('0123456789');if($('sy').checked)sets.push('!@#$%^&*()-_=+[]{};:,.?/');if(!sets.length){GWB.status('str','Choose at least one character type above to generate passwords.','error');return}
if($('am').checked)sets=sets.map(s=>s.replace(/[O0Il1|]/g,''));const all=sets.join(''),L=+$('len').value;$('list').innerHTML='';
for(let k=0;k<5;k++){let p=sets.map(s=>s[pick(s.length)]);while(p.length<L)p.push(all[pick(all.length)]);for(let i=p.length-1;i>0;i--){const j=pick(i+1);[p[i],p[j]]=[p[j],p[i]]}p=p.join('');
const li=document.createElement('li'),code=document.createElement('code'),b=document.createElement('button');code.textContent=p;b.className='alt';b.textContent='Copy';b.setAttribute('aria-label','Copy password '+(k+1));b.onclick=()=>{GWB.copy(p,null,'Password copied.');b.textContent='Copied'};li.append(code,' ',b);$('list').append(li)}
const bits=Math.round(L*Math.log2(all.length));GWB.status('str','');$('str').textContent=`Strength: about ${bits} bits of entropy (${bits>=100?'excellent':bits>=72?'strong':bits>=50?'fair':'weak'}).`}
$('len').addEventListener('input',()=>{$('lv').textContent=$('len').value;gen()});document.querySelectorAll('#tool input[type=checkbox]').forEach(c=>c.onchange=gen);$('gen').onclick=gen;gen();""")
apps['biz-calc']=page("Business Calculators: Margin, Sales Tax, Loan & Break-Even","Four everyday small-business calculators in one place: profit margin and markup, sales tax, loan payments and break-even point.",
"Type your numbers into any calculator. Results update instantly. Use any currency; amounts are shown with two decimals.",
r"""<h2>Calculators</h2><div class="grid">
<fieldset><legend>Profit margin &amp; markup</legend><label for="mc">Cost</label><input id="mc" type="number" min="0" step="any" value="40"><label for="mp">Selling price</label><input id="mp" type="number" min="0" step="any" value="65"><output id="mo" class="out" for="mc mp" aria-live="polite" style="display:block"></output></fieldset>
<fieldset><legend>Sales tax</legend><label for="ta">Amount</label><input id="ta" type="number" min="0" step="any" value="100"><label for="tr">Tax rate (%)</label><input id="tr" type="number" min="0" max="100" step="any" value="8.875"><label class="check"><input type="checkbox" id="ti"> Amount already includes tax</label><output id="to" class="out" aria-live="polite" style="display:block"></output></fieldset>
<fieldset><legend>Loan payment</legend><label for="la">Loan amount</label><input id="la" type="number" min="0" step="any" value="25000"><label for="lr">Annual interest rate (%)</label><input id="lr" type="number" min="0" max="100" step="any" value="7.5"><label for="ly">Term (years)</label><input id="ly" type="number" min="0" max="100" step="any" value="5"><output id="lo" class="out" aria-live="polite" style="display:block"></output></fieldset>
<fieldset><legend>Break-even point</legend><label for="bf">Fixed costs (per month)</label><input id="bf" type="number" min="0" step="any" value="3000"><label for="bp">Price per unit</label><input id="bp" type="number" min="0" step="any" value="25"><label for="bv">Variable cost per unit</label><input id="bv" type="number" min="0" step="any" value="10"><output id="bo" class="out" aria-live="polite" style="display:block"></output></fieldset></div>""",
r"""const N=(id,o)=>GWB.num(id,o),o=(id,t)=>document.getElementById(id).textContent=t,f=x=>x.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}),FIX='Fix the highlighted field above to see this result.',M=1e12,ok=(...a)=>a.every(x=>x!==null);
function calc(){const c=N('mc',{label:'Cost',min:0,max:M}),p=N('mp',{label:'Selling price',gt:0,max:M});if(ok(c,p)){const pr=p-c;o('mo',`Profit: ${f(pr)}\nMargin: ${f(pr/p*100)}%\nMarkup: ${c>0?f(pr/c*100)+'%':'n/a (cost is 0)'}`)}else o('mo',FIX);
const a=N('ta',{label:'Amount',min:0,max:M}),r0=N('tr',{label:'Tax rate',min:0,max:100});if(ok(a,r0)){const r=r0/100;if(document.getElementById('ti').checked){const pre=a/(1+r);o('to',`Pre-tax price: ${f(pre)}\nTax included: ${f(a-pre)}`)}else o('to',`Tax: ${f(a*r)}\nTotal: ${f(a*(1+r))}`)}else o('to',FIX);
const L=N('la',{label:'Loan amount',min:0,max:M}),lr=N('lr',{label:'Interest rate',min:0,max:100}),ly=N('ly',{label:'Term',gt:0,max:100});if(ok(L,lr,ly)){const i=lr/1200,n=Math.max(1,Math.round(ly*12)),m=i?L*i/(1-Math.pow(1+i,-n)):L/n;o('lo',`Monthly payment: ${f(m)}\nTotal paid: ${f(m*n)}\nTotal interest: ${f(m*n-L)}`)}else o('lo',FIX);
const bf=N('bf',{label:'Fixed costs',min:0,max:M}),bp=N('bp',{label:'Price per unit',min:0,max:M}),bv=N('bv',{label:'Variable cost',min:0,max:M});if(!ok(bf,bp,bv))o('bo',FIX);else if(bp<=bv)o('bo','Price must be higher than the variable cost per unit.');else{const u=Math.ceil(bf/(bp-bv));o('bo',`Break-even: ${u.toLocaleString()} units\nRevenue needed: ${f(u*bp)}`)}}
document.querySelectorAll('#tool input').forEach(x=>x.addEventListener('input',calc));calc();""")
apps['business-name']=page("Business Name Generator","Brainstorm short, brandable business name ideas from your own keywords, then shortlist your favorites.",
"Enter one or two keywords that describe your business, pick a style, and generate fresh ideas. Click Generate again for more. Always check trademark and domain availability before choosing.",
r"""<h2>Generate names</h2><div class="grid"><div><label for="kw">Keyword(s)</label><input id="kw" value="bloom bakery"></div><div><label for="tone">Style</label><select id="tone"><option value="modern">Modern</option><option value="classic">Classic</option><option value="playful">Playful</option><option value="tech">Tech</option></select></div></div>
<button type="button" id="go">Generate names</button><ul id="list" class="grid" style="list-style:none;padding:0;margin-top:18px" aria-live="polite"></ul><p class="lead"><small>Ideas only. Check trademark databases, business registries and domain availability before using a name.</small></p>""",
r"""const $=id=>document.getElementById(id),T={modern:{pre:['Nova','Bright','True','Prime','Pure','Bold'],suf:['Co','Studio','Lab','House','Collective','Works']},classic:{pre:['Royal','Heritage','Golden','Oak','Crown','Sterling'],suf:['& Co.','Brothers','Guild','Company','Traders','Establishment']},playful:{pre:['Happy','Little','Jolly','Sunny','Lucky','Busy'],suf:['Spot','Nest','Pop','Party','Corner','Buddies']},tech:{pre:['Neo','Hyper','Smart','Quantum','Cloud','Pixel'],suf:['ify','ly','Hub','Stack','IQ','Base']}};
const cap=s=>{const c=[...s];return c.length?c[0].toLocaleUpperCase()+c.slice(1).join(''):s},r=a=>a[Math.floor(Math.random()*a.length)];
function gen(){const raw=GWB.text('kw',{label:'Keyword',max:200});if(raw===null)return;const w=[...new Set(raw.toLocaleLowerCase().split(/[^\p{L}\p{N}]+/u).filter(Boolean))].slice(0,20);if(!w.length)return GWB.fieldError('kw','Enter at least one keyword using letters or numbers (for example "bakery").');const t=T[$('tone').value],set=new Set();let guard=0;
while(set.size<18&&guard++<300){const a=r(w),b=r(w),s=r(t.suf),p=r(t.pre),k=Math.floor(Math.random()*6);let n;
if(k==0)n=cap(a)+(s.length<4&&/^[a-z]/.test(s)?s:' '+s);else if(k==1)n=p+' '+cap(a);else if(k==2)n=cap(a.slice(0,Math.ceil(a.length*.6)))+(b!==a?b.slice(Math.floor(b.length/2)):r(['io','a','o','ly']));else if(k==3)n=cap(a)+' & '+cap(r(['Co.','Crumb','Leaf','Stone','Field','Lane']));else if(k==4)n='The '+cap(a)+' '+r(t.suf.filter(x=>/^[A-Z]/.test(x)));else n=p+cap(a);set.add(n.trim())}
$('list').innerHTML='';[...set].forEach(n=>{const li=document.createElement('li');li.className='stat';li.textContent=n;$('list').append(li)})}
$('go').onclick=gen;$('kw').addEventListener('change',gen);$('tone').addEventListener('change',gen);gen();""")
